package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryEvaluationStep;
import org.eclipse.rdf4j.query.explanation.QueryExplanationContext;
import org.eclipse.rdf4j.query.explanation.StrategyDecision;

/** Cold, compilation-scoped diagnostic helpers. No execution opener may run in this scope. */
final class LmdbNativeStrategyPreview {
	private LmdbNativeStrategyPreview() {
	}

	static boolean active() {
		return QueryExplanationContext.isPreview();
	}

	static void inspect(QueryEvaluationStep step) {
		if (step instanceof LmdbNativePhysicalPlan physical && QueryExplanationContext.inspectOnce(step)) {
			physical.explainStrategies();
		}
	}

	static void record(TupleExpr target, StrategyDecision decision) {
		QueryExplanationContext.record(decision);
	}

	static void empty(String point, String reason) {
		List<StrategyDecision.Candidate> candidates = LmdbNativeStrategyCatalog.names()
				.stream()
				.map(tag -> new StrategyDecision.Candidate(tag, null, false, "Not needed", reason, null))
				.toList();
		record(null,
				new StrategyDecision(point, System.currentTimeMillis(), "no dispatch", null, null, reason, candidates));
	}

	static void direct(String point, String tag, String reason, String fallback) {
		List<StrategyDecision.Candidate> candidates = new ArrayList<>();
		candidates.add(new StrategyDecision.Candidate(tag, 1, true, "Would select now", null, reason));
		if (fallback != null) {
			candidates.add(new StrategyDecision.Candidate(fallback, 2, true, "Fallback", null,
					"Used if the direct strategy cannot bind at execution time"));
		}
		for (String name : LmdbNativeStrategyCatalog.names()) {
			if (!name.equals(tag) && !name.equals(fallback)) {
				String requirement = LmdbNativeStrategyCatalog.otherSiteReason(name, point);
				candidates.add(new StrategyDecision.Candidate(name, null, false, "Declined",
						requirement != null ? requirement : "This direct dispatch requires " + tag + ": " + reason,
						null));
			}
		}
		record(null,
				new StrategyDecision(point, System.currentTimeMillis(), "direct", tag, fallback, reason, candidates));
	}

	static void runtime(String point, List<String> strategies, String condition) {
		List<StrategyDecision.Candidate> candidates = new ArrayList<>();
		for (String strategy : strategies) {
			candidates.add(new StrategyDecision.Candidate(strategy, null, null, "Runtime dependent", null, condition));
		}
		for (String name : LmdbNativeStrategyCatalog.names()) {
			if (!strategies.contains(name)) {
				candidates.add(new StrategyDecision.Candidate(name, null, false, "Declined",
						"This decision selects the type-matrix morsel traversal", null));
			}
		}
		record(null, new StrategyDecision(point, System.currentTimeMillis(), "runtime dependent", null, null,
				condition, candidates));
	}

	static void inspect(SlotPlan plan) {
		if (!QueryExplanationContext.inspectOnce(plan)) {
			return;
		}
		if (plan instanceof NativeSubqueryPlan subquery) {
			subquery.explainStrategies();
		} else if (plan instanceof MultiJoinPlan join) {
			for (SlotPlan child : join.children) {
				inspect(child);
			}
			for (MaskedFilter filter : join.filters) {
				inspect(filter.filter);
			}
		} else if (plan instanceof JoinPlan join) {
			inspect(join.left);
			inspect(join.right);
		} else if (plan instanceof LeftJoinPlan join) {
			inspect(join.left);
			inspect(join.right);
		} else if (plan instanceof LateralPlan join) {
			inspect(join.left);
			QueryExplanationContext.withRuntimeCondition("Outer LATERAL row bindings are required",
					() -> inspect(join.right));
		} else if (plan instanceof UnionPlan union) {
			inspect(union.left);
			inspect(union.right);
		} else if (plan instanceof OrderedUnionPlan union) {
			inspect(union.left);
			inspect(union.right);
		} else if (plan instanceof MinusPlan minus) {
			inspect(minus.left);
			inspect(minus.right);
		} else if (plan instanceof FilterPlan filter) {
			inspect(filter.arg);
			inspect(filter.filter);
		} else if (plan instanceof ExtensionPlan extension) {
			inspect(extension.arg);
		} else if (plan instanceof EntryBindingCompatibilityPlan entry) {
			inspect(entry.arg);
		} else if (plan instanceof MergeOrderedJoinPlan merge) {
			inspect(merge.join);
		} else if (plan instanceof DrainGuardPlan guard) {
			inspect(guard.delegate);
			inspect(guard.drained);
		}
	}

	static void inspect(NativeBooleanFilter filter) {
		if (!QueryExplanationContext.inspectOnce(filter)) {
			return;
		}
		if (filter instanceof ExistsFilter exists) {
			inspect(exists.subPlan);
		} else if (filter instanceof RecordingNativeBooleanFilter recording) {
			inspect(recording.delegate);
		} else if (filter instanceof NegatedNativeBooleanFilter negated) {
			inspect(negated.delegate);
		} else if (filter instanceof BooleanCombinationFilter combined) {
			inspect(combined.left);
			inspect(combined.right);
		} else if (filter instanceof NativeConstantFalseWhenUnboundFilter guarded) {
			inspect(guarded.fallback);
		} else {
			filter.explainStrategies();
		}
	}

	static String unavailableReason(String tag, String point) {
		String otherSite = LmdbNativeStrategyCatalog.otherSiteReason(tag, point);
		if (otherSite != null) {
			return otherSite;
		}
		if (tag.contains("Interpreted") && !LmdbNativeKernelInterpreter.enabled())
			return "Interpreted kernels are disabled";
		if ((tag.startsWith("ir") && !tag.contains("Interpreted") || tag.equals("janinoAggregate"))
				&& !LmdbNativeJaninoCodegen.enabled())
			return "Compiled kernels are disabled";
		if (tag.equals("packedFtree") || tag.equals("packedFtreeAggregate")) {
			if (!LmdbNativePackedFtree.enabled())
				return "Packed f-tree execution is disabled";
		}
		if ((tag.equals("parallelPipelines") || tag.equals("parallelAggregation"))
				&& !LmdbNativeParallelPipelines.enabled())
			return "Parallel pipelines are disabled";
		if (tag.equals("batch") && !NativeBatch.enabled())
			return "Batch execution is disabled";
		return switch (tag) {
		case "prefixRun" -> "No prefix-run plan over an unbound leading pattern";
		case "orderedDistinct" -> "No unsorted DISTINCT input with an ordered deduplication plan";
		case "wcoj" -> LmdbNativeLeapfrogJoin.enabled()
				? "No compatible cyclic join with all existential patterns in its cyclic core"
				: "Worst-case-optimal joins are disabled";
		case "wildcardPredicateBatch", "wildcardPredicateReduced" -> "No supported wildcard-predicate batch shape";
		case "typeMatrix" -> "No type-matrix aggregate recognized, or incoming bindings prevent type-matrix execution";
		case "adjacencyAggregate" -> "No adjacency aggregate matching the group keys, aggregates and incoming bindings";
		case "existsIntersection" -> "No aggregate over a recognized EXISTS intersection";
		case "prefixRunGroups" -> "No aggregate prefix-run plan over an unbound leading pattern";
		case "orderedDistinctGroups" -> "No replay-safe aggregate with an ordered DISTINCT input";
		case "orderedSinglePatternGroups" -> "No replay-safe, ordered aggregate over a single pattern";
		case "factorizedTail" -> "No separable aggregate tail retaining the group and aggregate variables";
		case "factorizedRows", "packedFtree", "packedFtreeAggregate", "janinoAggregate", "parallelAggregation" -> "The compiled input is not a multi-pattern join supported by this strategy";
		case "orderedFactorizedSort" -> "Requires an unbounded ORDER BY without DISTINCT or computed sort values";
		case "orderedFactorizedTopK" -> "Requires a bounded ORDER BY without DISTINCT or computed sort values";
		case "orderedTopK", "orderedFullSort" -> "General sorting is the fallback after ordered specialists decline";
		case "irKernelDistinct", "irKernelDistinctInterpreted", "irKernelDistinctParallel", "irKernelDistinctParallelInterpreted" -> "Requires a DISTINCT terminal with projected slots and a fusible input";
		case "irKernelWildcard", "irKernelWildcardInterpreted", "irAggregateWildcard", "irAggregateWildcardInterpreted" -> "Requires a supported wildcard-predicate terminal";
		case "irAggregateNodeDomainIntersection" -> "Requires a recognized node-domain intersection aggregate";
		case "irAggregateTypeMatrix", "irAggregateTypeMatrixInterpreted", "irAggregateTypeMatrixParallel", "irAggregateTypeMatrixParallelInterpreted" -> "Requires a recognized type-matrix aggregate terminal";
		case "irAggregate", "irAggregateInterpreted", "irAggregateParallel", "irAggregateParallelInterpreted" -> "This aggregate dispatch uses a specialized terminal or an algorithmic specialist";
		case "irKernel", "irKernelInterpreted", "irKernelParallel", "irKernelParallelInterpreted" -> "The compiled row terminal uses a specialized wildcard route";
		default -> "This strategy is not offered at " + point;
		};
	}
}
